using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using PeerChatDesktop;
class AdapterTest {
    static void Require(bool condition,string reason){if(!condition)throw new Exception(reason);}
    static void Until(Func<bool> check,Action pump,string label){var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<20000){pump();if(check())return;Thread.Sleep(30);}throw new Exception("Timeout: "+label);}
    static void CopyDirectory(string source,string target){Directory.CreateDirectory(target);foreach(string file in Directory.GetFiles(source))File.Copy(file,Path.Combine(target,Path.GetFileName(file)),true);foreach(string child in Directory.GetDirectories(source))CopyDirectory(child,Path.Combine(target,Path.GetFileName(child)));}
    static void TestFriendConversationIdentity(string root){
        string oldPeer=new string('a',64),newPeer=new string('b',64),profileA=Path.Combine(root,"social-A"),profileB=Path.Combine(root,"social-B");
        Func<byte[],byte[]> identity=data=>data;var friend=new DiscoverySearchResult{AccountId=42,Username="Alice",PublicIdentity=oldPeer,Online=false};var index=new FriendConversationIndex(profileA,identity,identity);index.Reconcile(new[]{friend});
        var loaded=new FriendConversationIndex(profileA,identity,identity);Require(loaded.Records.Single().CurrentPeerId==oldPeer,"Friend mapping did not persist in its profile");Require(!new FriendConversationIndex(profileB,identity,identity).Records.Any(),"Friend mapping leaked into another profile");
        var view=new ChatViewModel();bool reused;var conversation=view.BindFriend(42,"Alice",oldPeer,loaded.Records.Single().KnownPeerIds,out reused);Require(!reused&&conversation.ConversationId=="account:42","Stable account conversation was not created");
        view.Apply(new CoreEvent{kind=1,contacts=new[]{new ContactData{peer=oldPeer,name="old",verified=true}}});view.Apply(new CoreEvent{kind=6,peer=oldPeer,messages=new[]{new MessageData{id="old",sender=oldPeer,text="offline",logical=1}}});
        var same=view.BindFriend(42,"Alice Renamed",newPeer,new[]{oldPeer,newPeer},out reused);Require(reused&&Object.ReferenceEquals(conversation,same)&&view.Conversations.Count==1,"Device change created a duplicate conversation");Require(same.Name=="Alice Renamed"&&same.PreviousVerifiedPeerId==oldPeer&&!same.Contact.verified,"Name/device reconciliation bypassed identity verification");
        view.Apply(new CoreEvent{kind=6,peer=newPeer,messages=new[]{new MessageData{id="new",sender=newPeer,text="online",logical=2}}});Require(same.Messages.Count==2&&Object.ReferenceEquals(view.FindByPeer(oldPeer),view.FindByPeer(newPeer)),"Old and new device history did not merge into one social conversation");
        var log=new ConnectionDiagnosticLog(profileA);for(int i=0;i<600;i++)log.Record("tcp",42,"account:42",newPeer,newPeer,"192.0.2.1:7777","discovery","LAN","TCP timeout");Require(new FileInfo(Path.Combine(profileA,"connection.log")).Length<=160000,"Connection log was not bounded");
        string peerTwo=new string('c',64),wrongPeer=new string('d',64);var second=view.BindFriend(43,"Bob",peerTwo,new[]{peerTwo},out reused);var tracker=new ConnectionAttemptTracker();tracker.Update(new CoreEvent{expected=newPeer,peer=newPeer,candidate="192.0.2.10:7777",source="Discovery LAN candidate",route="same LAN",attempt=11},same,"Connecting",null,"TCP timeout");tracker.Update(new CoreEvent{expected=peerTwo,peer=peerTwo,candidate="198.51.100.20:8888",source="Server-observed Internet address",route="public fallback",attempt=12},second,"Connecting",null,"Connection refused");Require(tracker.For(same).ExpectedPeer==newPeer&&tracker.For(same).Candidate=="192.0.2.10:7777"&&tracker.For(same).Failure=="TCP timeout","Account A diagnostics were overwritten");Require(tracker.For(second).ExpectedPeer==peerTwo&&tracker.For(second).Candidate=="198.51.100.20:8888"&&tracker.For(second).Failure=="Connection refused","Account B diagnostics were not independently correlated");int conversations=view.Conversations.Count;view.Apply(new CoreEvent{kind=2,expected=newPeer,peer=wrongPeer,text="Peer identity changed"});Require(view.Conversations.Count==conversations&&same.Contact.peer==newPeer&&!Object.ReferenceEquals(view.FindByPeer(wrongPeer),same),"Wrong-identity fallback created or rebound a conversation before verification");
    }
    static void TestProfileAccountBinding(string root){
        Func<byte[],byte[]> identity=data=>data;string aPath=Path.Combine(root,"account-A"),bPath=Path.Combine(root,"account-B");
        var a=new ProfileAccountStore(aPath,identity,identity);a.SaveSession(1001,"account-a","localhost",7443,"pin-a","token-a");var loaded=new ProfileAccountStore(aPath,identity,identity).Load();Require(loaded.AccountId==1001&&loaded.Username=="account-a"&&loaded.SessionToken=="token-a","Protected profile account session did not survive reload");
        bool mismatch=false;try{a.SaveSession(2002,"account-b","localhost",7443,"pin-b","token-b");}catch(InvalidOperationException){mismatch=true;}Require(mismatch&&a.Load().AccountId==1001,"A profile silently changed to B account");
        var b=new ProfileAccountStore(bPath,identity,identity);b.SaveSession(2002,"account-b","localhost",7443,"pin-b","token-b");a.ClearSession();Require(a.Load().AccountId==1001&&!a.Load().HasSession,"Signing out removed the durable A account binding");Require(b.Load().AccountId==2002&&b.Load().SessionToken=="token-b","Signing out A altered B profile's session");
        string damagedPath=Path.Combine(root,"account-damaged");Directory.CreateDirectory(damagedPath);File.WriteAllText(Path.Combine(damagedPath,"account-link.dat"),"damaged");var damaged=new ProfileAccountStore(damagedPath,identity,identity);bool damagedRefused=false;try{damaged.SaveSession(3003,"account-c","localhost",7443,"pin-c","token-c");}catch(InvalidOperationException){damagedRefused=true;}Require(damaged.Exists&&damaged.Load()==null&&damagedRefused,"An unreadable account binding was mistaken for a new unlinked profile");
    }
    static int Main(){try{
        string root=Path.Combine(Environment.CurrentDirectory,"build","tests","runtime","desktop-"+Guid.NewGuid().ToString("N"));
        TestFriendConversationIdentity(root);
        TestProfileAccountBinding(root);
        var a=new CoreAdapter();var b=new CoreAdapter();var av=new ChatViewModel();var bv=new ChatViewModel();
        Action pump=()=>{foreach(var pair in new[]{Tuple.Create(a,av),Tuple.Create(b,bv)})foreach(var e in pair.Item1.Poll()){if(e.kind==8&&!e.text.StartsWith("Voice audio device error:"))throw new Exception(e.text);pair.Item2.Apply(e);if(e.kind==2)pair.Item1.Approve(e.peer,true);}};
        try{
            a.Start(Path.Combine(root,"A"),29431,"Alice");b.Start(Path.Combine(root,"B"),29432,"Bob");
            Until(()=>av.Listening&&bv.Listening,pump,"listeners");string aId=av.OwnId,bId=bv.OwnId;
            string invite=b.Share("127.0.0.1",bv.Port,bv.OwnId);Require(invite.StartsWith("P2PCHAT1:"),"Share format");Require(a.Add("bad",av.OwnId).Length>0,"Invalid ID was accepted");Require(a.Add(invite,av.OwnId)=="","Add Friend");
            Until(()=>av.Conversations.Values.Any(c=>c.Online)&&bv.Conversations.Values.Any(c=>c.Online),pump,"mutual TLS and trust");
            string text="Hello \"friend\" \\ Unicode ☃ https://example.com/\nsecond line";
            Require(a.Send(bId,text),"Send A to B");Require(b.Send(aId,"Reply from Bob"),"Send B to A");
            Until(()=>av.Get(bId).Messages.Count==2&&bv.Get(aId).Messages.Count==2&&av.Get(bId).Messages.Any(m=>m.Outgoing&&m.Data.delivery==2)&&bv.Get(aId).Messages.Any(m=>m.Outgoing&&m.Data.delivery==2),pump,"bidirectional messages and acknowledgements");
            Require(bv.Get(aId).Messages.Any(m=>m.Text==text),"UTF-16/JSON payload changed");
            Require(a.SetGroupAccount(7001,"Alice account")&&b.SetGroupAccount(7002,"Bob account"),"Group account binding failed");string groupId=a.CreateGroup("Adapter group");Require(groupId.Length==32,"Client did not create a random Group ID");Until(()=>av.GroupChats.ContainsKey(groupId),pump,"local group creation");Require(a.InviteToGroup(groupId,7002,bId,"Bob account"),"Signed group invite was not queued");Until(()=>bv.GroupChats.ContainsKey(groupId)&&bv.GroupChats[groupId].Invited,pump,"group invite through adapter");Require(b.RespondToGroupInvite(groupId,true),"Group acceptance was not queued");Until(()=>av.GroupChats[groupId].MemberCount==2&&bv.GroupChats[groupId].MemberCount==2,pump,"group membership convergence through adapter");Require(a.SendGroup(groupId,"Adapter group message"),"Group message was not queued");Until(()=>av.GroupChats[groupId].Messages.Any(m=>m.Text.EndsWith("Adapter group message"))&&bv.GroupChats[groupId].Messages.Any(m=>m.Text.EndsWith("Adapter group message")),pump,"group message JSON bridge");
            var devices=a.VoiceDevices();Require(devices.inputs.Length>0&&devices.outputs.Length>0&&a.SelectVoiceDevices(devices.inputs[0].id,devices.outputs[0].id),"Voice device selection bridge failed");string callId=a.StartVoiceCall(bId);Require(callId.Length==32,"Voice call bridge did not return a call ID");Until(()=>bv.VoiceState.StartsWith("Incoming")&&bv.VoiceCallId==callId,pump,"Voice call bridge did not deliver ringing state");Require(b.AnswerVoiceCall(callId),"Voice answer bridge rejected the call");Until(()=>av.VoiceState.StartsWith("Connected")&&bv.VoiceState.StartsWith("Connected"),pump,"Voice call bridge did not connect both peers");Require(a.SetVoiceMuted(true)&&a.SetVoiceMuted(false)&&b.SetVoiceDeafened(true)&&b.SetVoiceDeafened(false),"Mute/deafen bridge rejected a connected call");Require(b.EndVoiceCall(callId),"Voice hang-up bridge rejected the call");Until(()=>av.VoiceState.StartsWith("Idle")&&bv.VoiceState.StartsWith("Idle"),pump,"Voice hang-up did not clear managed call state");
            a.Dispose();b.Dispose();a=new CoreAdapter();b=new CoreAdapter();av=new ChatViewModel();bv=new ChatViewModel();
            a.Start(Path.Combine(root,"A"),29431,"");b.Start(Path.Combine(root,"B"),29432,"");
            Until(()=>av.Listening&&bv.Listening&&av.Conversations.Values.Any(c=>c.Online)&&bv.Conversations.Values.Any(c=>c.Online),pump,"restart and reconnect");
            Require(av.OwnId==aId&&bv.OwnId==bId,"Identity changed");a.History(bId,long.MaxValue);b.History(aId,long.MaxValue);
            Until(()=>av.Get(bId).Messages.Count==2&&bv.Get(aId).Messages.Count==2,pump,"encrypted history reload");
            a.Dispose();b.Dispose();string install=Path.Combine(root,"managed-install");Directory.CreateDirectory(install);CopyDirectory(Path.Combine(root,"A"),install);
            var profiles=new LocalProfileManager(install);var migratedCatalog=profiles.Initialize();var profileA=migratedCatalog.Profiles.Single();Require(profileA.MigratedLegacy,"Legacy state was not identified for migration");Require(File.Exists(Path.Combine(install,"peerchat.sqlite")),"Legacy source was removed");
            a=new CoreAdapter();av=new ChatViewModel();Action pumpA=()=>{foreach(var e in a.Poll()){if(e.kind==8)throw new Exception(e.text);av.Apply(e);}};a.Start(profiles.ProfilePath(profileA.Id),29531,"");Until(()=>av.Listening,pumpA,"migrated profile start");Require(av.OwnId==aId,"Legacy migration changed Peer ID");a.History(bId,long.MaxValue);Until(()=>av.Get(bId).Messages.Count==2,pumpA,"migrated encrypted history");Require(av.Get(bId).Contact.verified,"Legacy trust was not preserved");a.Dispose();
            var profileB=profiles.Create("Profile B");b=new CoreAdapter();bv=new ChatViewModel();Action pumpB=()=>{foreach(var e in b.Poll()){if(e.kind==8)throw new Exception(e.text);bv.Apply(e);}};b.Start(profiles.ProfilePath(profileB.Id),29532,"");Until(()=>bv.Listening,pumpB,"profile B start");string firstBId=bv.OwnId;Require(firstBId!=aId,"Profiles A and B shared a Peer ID");Require(bv.Conversations.Count==0,"Profile A trust or history appeared in B");b.Dispose();
            profiles.Select(profileA.Id);a=new CoreAdapter();av=new ChatViewModel();pumpA=()=>{foreach(var e in a.Poll()){if(e.kind==8)throw new Exception(e.text);av.Apply(e);}};a.Start(profiles.ProfilePath(profileA.Id),29531,"");Until(()=>av.Listening,pumpA,"switch B to A");Require(av.OwnId==aId&&av.FindByPeer(bId)!=null&&av.Get(bId).Contact.verified,"Switching A-B-A did not restore A state");a.Dispose();
            profiles.Select(profileB.Id);string backup=Path.Combine(root,"backup-B");profiles.BackupSelected(backup);profiles.ResetSelected(Path.Combine(root,"reset-B"));b=new CoreAdapter();bv=new ChatViewModel();pumpB=()=>{foreach(var e in b.Poll()){if(e.kind==8)throw new Exception(e.text);bv.Apply(e);}};b.Start(profiles.ProfilePath(profileB.Id),29532,"");Until(()=>bv.Listening,pumpB,"reset B");Require(bv.OwnId!=firstBId,"Reset B did not generate a new Peer ID");b.Dispose();
            profiles.RestoreSelected(Path.Combine(backup,"PeerChatProfile"),Path.Combine(root,"before-restore-B"));b=new CoreAdapter();bv=new ChatViewModel();pumpB=()=>{foreach(var e in b.Poll()){if(e.kind==8)throw new Exception(e.text);bv.Apply(e);}};b.Start(profiles.ProfilePath(profileB.Id),29532,"");Until(()=>bv.Listening,pumpB,"restore B");Require(bv.OwnId==firstBId,"Restore B did not restore its exact identity");b.Dispose();
            profiles.Select(profileA.Id);a=new CoreAdapter();av=new ChatViewModel();pumpA=()=>{foreach(var e in a.Poll()){if(e.kind==8)throw new Exception(e.text);av.Apply(e);}};a.Start(profiles.ProfilePath(profileA.Id),29531,"");Until(()=>av.Listening,pumpA,"A after B reset/restore");Require(av.OwnId==aId,"Reset or restore B altered A");a.History(bId,long.MaxValue);Until(()=>av.Get(bId).Messages.Count==2,pumpA,"A history after B restore");
            var replacement=new CoreAdapter();var replacementView=new ChatViewModel();var verifier=new CoreAdapter();var verifierView=new ChatViewModel();try{replacement.Start(Path.Combine(root,"replacement-device"),29533,"Replacement");verifier.Start(Path.Combine(root,"identity-verifier"),29534,"Verifier");Action pumpReplacement=()=>{foreach(var e in replacement.Poll()){replacementView.Apply(e);if(e.kind==2)replacement.Approve(e.peer,true);}foreach(var e in verifier.Poll())verifierView.Apply(e);};Until(()=>replacementView.Listening&&verifierView.Listening,pumpReplacement,"replacement identity peers");int prompts=0;string warning="";verifier.Connect("127.0.0.1",replacementView.Port,bId);Action pumpIdentityChange=()=>{foreach(var e in verifier.Poll()){verifierView.Apply(e);if(e.kind==2){prompts++;warning=e.text;}}foreach(var e in replacement.Poll()){replacementView.Apply(e);if(e.kind==2)replacement.Approve(e.peer,true);}};Until(()=>prompts==1,pumpIdentityChange,"replacement identity verification");var duplicateWindow=Stopwatch.StartNew();while(duplicateWindow.ElapsedMilliseconds<500){pumpIdentityChange();Thread.Sleep(20);}Require(prompts==1,"Replacement identity produced more than one verification prompt");Require(warning.Contains(bId)&&warning.Contains(replacementView.OwnId),"Identity warning did not show expected and presented Peer IDs");verifier.Approve(replacementView.OwnId,false);}finally{replacement.Dispose();verifier.Dispose();}
            Console.WriteLine("PASS: adapter, encrypted history/trust, legacy migration, isolated A/B switching/reset/restore, and one explicit expected/presented replacement-identity verification.");
        }finally{a.Dispose();b.Dispose();}return 0;
    }catch(Exception e){Console.Error.WriteLine("FAIL: "+e);return 1;}}
}
